# Terraform configuration for a MySQL Cloud SQL instance with Public IP access.

terraform {
  required_version = ">= 1.5.0"
  required_providers {
    google = {
      source  = "hashicorp/google"
      version = "~> 8.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.6"
    }
  }
}

variable "project_id" {
  type        = string
  description = "The GCP project ID where resources will be created."
}

variable "region" {
  type        = string
  description = "The GCP region for the Cloud SQL instance."
  default     = "us-central1"
}

variable "office_vpn_cidr" {
  type        = string
  description = "The public CIDR range of the office VPN allowed to access the Cloud SQL instance."
  default     = "198.51.100.0/24" # Example documentation IP range; replace with actual VPN IP
}

provider "google" {
  project = var.project_id
  region  = var.region
}

# Suffix to ensure uniqueness of Cloud SQL instance name
resource "random_id" "db_name_suffix" {
  byte_length = 4
}

# Strong password generation for the application database user
resource "random_password" "db_password" {
  length  = 24
  special = true
}

# Cloud SQL MySQL Instance configured with a Public IPv4 address
resource "google_sql_database_instance" "mysql_instance" {
  name             = "mysql-public-${random_id"db_name_suffix".hex}"
  database_version = "MYSQL_8_0"
  region           = var.region

  # Set to true in production to prevent accidental deletion
  deletion_protection = false

  settings {
    tier              = "db-custom-2-7680"
    availability_type = "ZONAL"
    disk_type         = "PD_SSD"
    disk_size         = 20
    disk_autoresize   = true

    backup_configuration {
      enabled            = true
      binary_log_enabled = true
      start_time         = "03:00"
    }

    ip_configuration {
      # Enable public IPv4 address assignment
      ipv4_enabled = true

      # Enforce SSL/TLS connections over the public internet
      ssl_mode = "ENCRYPTED_ONLY"

      # Whitelist the office VPN CIDR block
      authorized_networks {
        name  = "office-vpn"
        value = var.office_vpn_cidr
      }
    }

    insights_config {
      query_insights_enabled = true
    }
  }
}

# Application database
resource "google_sql_database" "app_database" {
  name     = "app_db"
  instance = google_sql_database_instance.mysql_instance.name
  charset  = "utf8mb4"
  collation = "utf8mb4_unicode_ci"
}

# Application database user configured for remote connections
resource "google_sql_user" "app_user" {
  name     = "app_user"
  instance = google_sql_database_instance.mysql_instance.name
  # Restrict host access or allow all matching connections
  host     = "%"
  password = random_password.db_password.result
}

# Outputs
output "instance_public_ip" {
  description = "The public IPv4 address assigned to the Cloud SQL instance."
  value       = google_sql_database_instance.mysql_instance.public_ip_address
}

output "instance_connection_name" {
  description = "The connection name of the Cloud SQL instance."
  value       = google_sql_database_instance.mysql_instance.connection_name
}

output "database_name" {
  description = "The name of the initial database."
  value       = google_sql_database.app_database.name
}

output "database_user" {
  description = "The username for accessing the database."
  value       = google_sql_user.app_user.name
}

output "database_password" {
  description = "The generated password for the database user."
  value       = random_password.db_password.result
  sensitive   = true
}

