  type        = string
  description = "The GCP project ID to host the storage bucket."
}

variable "bucket_name" {
  type        = string
  description = "Globally unique name for the Cloud Storage bucket."
}

variable "location" {
  type        = string
  description = "The location of the bucket (e.g., US, EU, ASIA, us-central1)."
  default     = "US"
}

resource "google_storage_bucket" "nearline_lifecycle_bucket" {
  name     = var.bucket_name
  project  = var.project_id
  location = var.location

  # Best practice: enforce Uniform Bucket Level Access
  uniform_bucket_level_access = true

  # Lifecycle rule to transition objects to NEARLINE storage after 30 days
  lifecycle_rule {
    action {
      type          = "SetStorageClass"
      storage_class = "NEARLINE"
    }

    condition {
      age = 30
    }
  }
}

