provider "google" {
  project = var.project_id
  region  = var.region
}

variable "project_id" {
  type        = string
  description = "The Google Cloud project ID."
}

variable "region" {
  type        = string
  description = "The GCP region to deploy resources in."
  default     = "us-central1"
}

# Generate a random suffix for the Cloud SQL instance name to avoid collisions
resource "random_id" "db_suffix" {
  byte_length = 4
}

# Generate a secure password for the database user
resource "random_password" "user_password" {
  length           = 16
  special          = true
  override_special = "!#$%&*()-_=+[]{}<>:?"
}

# Cloud SQL PostgreSQL Instance
resource "google_sql_database_instance" "postgres" {
  name             = "pg-instance-${random_id.db_suffix.hex}"
  database_version = "POSTGRES_15"
  region           = var.region

  # Set to true in production to prevent accidental deletion
  deletion_protection = false

  settings {
    tier = "db-custom-1-3840"

    ip_configuration {
      ipv4_enabled = true
    }

    backup_configuration {
      enabled                        = true
      point_in_time_recovery_enabled = true
    }
  }
}

# PostgreSQL Database
resource "google_sql_database" "appdb" {
  name     = "appdb"
  instance = google_sql_database_instance.postgres.name
}

# PostgreSQL Database User
resource "google_sql_user" "appuser" {
  name     = "appuser"
  instance = google_sql_database_instance.postgres.name
  password = random_password.user_password.result
}

# Outputs
output "instance_connection_name" {
  description = "The connection name of the Cloud SQL instance."
  value       = google_sql_database_instance.postgres.connection_name
}

output "instance_public_ip" {
  description = "The public IPv4 address of the Cloud SQL instance."
  value       = google_sql_database_instance.postgres.public_ip_address
}

output "database_name" {
  description = "The name of the database."
  value       = google_sql_database.appdb.name
