# Dedicated service account for GKE node instances adhering to least privilege
resource "google_service_account" "gke_nodes" {
  account_id   = "gke-cluster-nodes-sa"
  display_name = "GKE Node Pool Service Account"
}

# Regional private GKE cluster with Workload Identity enabled
resource "google_container_cluster" "primary" {
  name     = "primary-gke-cluster"
  location = var.region

  # Remove default unmanaged node pool in favor of an explicit node pool resource
  remove_default_node_pool = true
  initial_node_count       = 1

  # Required environment label per platform standards
  resource_labels = {
    environment = var.environment
  }

  # Private cluster configuration: nodes do not have public IP addresses
  private_cluster_config {
    enable_private_nodes = true
  }

  # Workload Identity configuration
  workload_identity_config {
    workload_pool = "${var.project_id}.svc.id.goog"
  }

  # Recommended release channel rather than pinned k8s versions
  release_channel {
    channel = "REGULAR"
  }
}

# Explicitly managed primary node pool
resource "google_container_node_pool" "primary_nodes" {
  name       = "primary-node-pool"
  cluster    = google_container_cluster.primary.name
  location   = var.region
  node_count = 1 # 1 node per zone across the region (total: 3 nodes)

  node_config {
    machine_type    = "e2-medium"
    service_account = google_service_account.gke_nodes.email
    oauth_scopes    = ["https://www.googleapis.com/auth/cloud-platform"]

    # Workload metadata configuration enabling Workload Identity for pods on these nodes
    workload_metadata_config {
      mode = "GKE_METADATA"
    }
  }
}

