# Terraform configuration for a Pub/Sub subscription with a dead-letter topic
# that routes messages after 5 delivery attempts.

terraform {
  required_version = ">= 1.5.0"
  required_providers {
    google = {
      source  = "hashicorp/google"
      version = "~> 8.0"
    }
  }
}

provider "google" {}

# Fetch the current project to construct the Pub/Sub service agent identity
data "google_project" "project" {}

# Main topic receiving initial messages
resource "google_pubsub_topic" "main" {
  name = "example-main-topic"
}

# Dead-letter topic receiving messages after delivery failure threshold
resource "google_pubsub_topic" "dead_letter" {
  name = "example-dead-letter-topic"
}

# Grant the Cloud Pub/Sub service agent permission to publish to the dead-letter topic
resource "google_pubsub_topic_iam_member" "dead_letter_publisher" {
  topic  = google_pubsub_topic.dead_letter.id
  role   = "roles/pubsub.publisher"
  member = "serviceAccount:service-${data.google_project.project.number}@gcp-sa-pubsub.iam.gserviceaccount.com"
}

# Subscription with the configured dead-letter policy
resource "google_pubsub_subscription" "example" {
  name  = "example-subscription"
  topic = google_pubsub_topic.main.id

  # Dead-letter configuration giving up after 5 delivery attempts
  dead_letter_policy {
    dead_letter_topic     = google_pubsub_topic.dead_letter.id
    max_delivery_attempts = 5
  }

  # Ensure publisher permissions are established before configuring dead-lettering
  depends_on = [
    google_pubsub_topic_iam_member.dead_letter_publisher,
    google_pubsub_subscription_iam_member.dead_letter_subscriber
  ]
}

# Grant the Cloud Pub/Sub service agent permission to forward/acknowledge from the subscription
resource "google_pubsub_subscription_iam_member" "dead_letter_subscriber" {
  subscription = "projects/${data.google_project.project.project_id}/subscriptions/example-subscription"
  role         = "roles/pubsub.subscriber"
  member       = "serviceAccount:service-${data.google_project.project.number}@gcp-sa-pubsub.iam.gserviceaccount.com"
}

