# Terraform configuration for Google Cloud KMS Key Ring and automatically rotating Crypto Key

terraform {
  required_version = ">= 1.5.0"
  required_providers {
    google = {
      source  = "hashicorp/google"
      version = "~> 8.0"
    }
  }
}

variable "project_id" {
  description = "The GCP project ID where KMS resources will be created."
  type        = string
}

variable "location" {
  description = "The location for the KMS Key Ring (e.g., 'us-central1' or 'global')."
  type        = string
  default     = "us-central1"
}

variable "key_ring_name" {
  description = "The name of the Cloud KMS Key Ring."
  type        = string
  default     = "example-key-ring"
}

variable "crypto_key_name" {
  description = "The name of the Cloud KMS CryptoKey."
  type        = string
  default     = "example-symmetric-key"
}

# KMS Key Ring
resource "google_kms_key_ring" "key_ring" {
  project  = var.project_id
  name     = var.key_ring_name
  location = var.location
}

# Symmetric CryptoKey with 90-day automatic rotation
# 90 days = 90 * 24 * 60 * 60 seconds = 7,776,000s
resource "google_kms_crypto_key" "crypto_key" {
  name            = var.crypto_key_name
  key_ring        = google_kms_key_ring.key_ring.id
  purpose         = "ENCRYPT_DECRYPT"
  rotation_period = "7776000s"

  lifecycle {
    prevent_destroy = false
  }
}

output "key_ring_id" {
  description = "The fully qualified identifier of the created KMS Key Ring."
  value       = google_kms_key_ring.key_ring.id
}

output "crypto_key_id" {
  description = "The fully qualified identifier of the created KMS CryptoKey."
  value       = google_kms_crypto_key.crypto_key.id
}

