# Terraform configuration for hosting a public static website using Google Cloud Storage

terraform {
  required_version = ">= 1.5.0"
  required_providers {
    google = {
      source  = "hashicorp/google"
      version = "~> 8.0"
    }
  }
}

variable "project_id" {
  description = "The GCP project ID where the resources will be created."
  type        = string
}

variable "bucket_name" {
  description = "The globally unique name for the website bucket (e.g., example.com if mapping a custom domain)."
  type        = string
}

variable "location" {
  description = "The location/region for the Cloud Storage bucket."
  type        = string
  default     = "US"
}

provider "google" {
  project = var.project_id
}

# Cloud Storage bucket configured for static website hosting
resource "google_storage_bucket" "static_website" {
  name                        = var.bucket_name
  location                    = var.location
  uniform_bucket_level_access = true
  force_destroy               = false

  website {
    main_page_suffix = "index.html"
    not_found_page   = "404.html"
  }

  cors {
    origin          = ["*"]
    method          = ["GET", "HEAD"]
    response_header = ["*"]
    max_age_seconds = 3600
  }
}

# IAM binding allowing anyone on the internet to view objects in the bucket
resource "google_storage_bucket_iam_member" "public_rule" {
  bucket = google_storage_bucket.static_website.name
  role   = "roles/storage.objectViewer"
  member = "allUsers"
}

output "bucket_name" {
  description = "The name of the created Cloud Storage bucket."
  value       = google_storage_bucket.static_website.name
}

output "website_url" {
  description = "The public web address for the static website."
  value       = "https://storage.googleapis.com/${google_storage_bucket.static_website.name}/index.html"
}

