# Terraform configuration for a MySQL Cloud SQL instance with a public IP
# and authorized network access for an office VPN.

terraform {
  required_version = ">= 1.5.0"
  required_providers {
    google = {
      source  = "hashicorp/google"
      version = "~> 8.0"
    }
    random = {
      source  = "hashicorp/random"
      version = ">= 3.0"
    }
  }
}

variable "project_id" {
  type        = string
  description = "The GCP project ID to deploy the Cloud SQL instance in."
}

variable "region" {
  type        = string
  description = "The GCP region for the Cloud SQL instance."
  default     = "us-central1"
}

variable "office_vpn_cidr" {
  type        = string
  description = "The public IP CIDR range of the office VPN to authorize access to MySQL."
  default     = "198.51.100.0/24"
}

provider "google" {
  project = var.project_id
  region  = var.region
}

# Unique suffix for instance naming
resource "random_id" "db_suffix" {
  byte_length = 4
}

# Generate a strong password for the database user
resource "random_password" "db_password" {
  length  = 24
  special = true
}

# Cloud SQL MySQL Instance with Public IPv4
resource "google_sql_database_instance" "mysql" {
  name             = "mysql-public-${random_id.db_suffix.hex}"
  database_version = "MYSQL_8_0"
  region           = var.region

  # Set to true in production to prevent accidental deletion
  deletion_protection = false

  settings {
    tier              = "db-custom-1-3840"
    availability_type = "ZONAL"
    disk_size         = 20
    disk_type         = "PD_SSD"

    backup_configuration {
      enabled    = true
      start_time = "03:00"
    }

    ip_configuration {
      # Enable public IPv4 address
      ipv4_enabled = true

      # Require SSL/TLS for all client connections
      ssl_mode = "ENCRYPTED_ONLY"

      # Restrict access to the Office VPN CIDR block
      authorized_networks {
        name  = "office-vpn"
        value = var.office_vpn_cidr
      }
    }
  }
}

# Default Application Database
resource "google_sql_database" "default" {
  name      = "app_db"
  instance  = google_sql_database_instance.mysql.name
  charset   = "utf8mb4"
  collation = "utf8mb4_unicode_ci"
}

# Application User
resource "google_sql_user" "app_user" {
  name     = "app_user"
  instance = google_sql_database_instance.mysql.name
  password = random_password.db_password.result
  host     = "%"
}

output "instance_connection_name" {
  description = "The connection name of the Cloud SQL instance."
  value       = google_sql_database_instance.mysql.connection_name
}

output "public_ip_address" {
  description = "The public IPv4 address assigned to the Cloud SQL instance."
  value       = google_sql_database_instance.mysql.public_ip_address
}

output "database_name" {
  description = "The name of the created MySQL database."
  value       = google_sql_database.default.name
}

output "database_user" {
  description = "The database username."
  value       = google_sql_user.app_user.name
}

output "database_password" {
  description = "The generated database user password."
  value       = random_password.db_password.result
  sensitive   = true
}

