resource "google_storage_bucket" "auto_delete_bucket" {
  name                        = "example-auto-delete-90-days-bucket"
  location                    = "US"
  uniform_bucket_level_access = true

  # Lifecycle rule to automatically delete objects 90 days after creation
  lifecycle_rule {
    condition {
      age = 90
    }
    action {
      type = "Delete"
    }
  }

  # Clean up incomplete multipart uploads after 7 days
  lifecycle_rule {
    condition {
      age = 7
    }
    action {
      type = "AbortIncompleteMultipartUpload"
    }
  }

  labels = {
    environment = "production"
    retention   = "90-days-auto-delete"
  }
}

