# Terraform configuration for a PostgreSQL 15 Cloud SQL instance
# Region defaults to asia-south1 per organizational standard.
# Secure defaults: private IP only, automated backups with PITR, deletion protection enabled, regional HA.

terraform {
  required_version = ">= 1.0"
  required_providers {
    google = {
      source  = "hashicorp/google"
      version = "~> 8.0"
    }
  }
}

