}

# The retrieved context specifies that private IP requires a private services access
# connection (google_service_networking_connection) on the VPC, but does not provide
# the full schema for VPC networking resources. Therefore, an existing VPC self_link is parameterized.
variable "private_network" {
  type        = string
  description = "The self_link of the VPC network with private services access enabled."
  default     = "projects/my-project/global/networks/shared-vpc"
}

resource "google_sql_database_instance" "postgres" {
  name                = "postgres15-instance"
  database_version    = "POSTGRES_15"
  region              = "asia-south1"
  deletion_protection = true

  settings {
    tier              = "db-custom-2-8192"
    availability_type = "REGIONAL"

    backup_configuration {
      enabled                        = true
      point_in_time_recovery_enabled = true
    }

    ip_configuration {
      ipv4_enabled    = false
      private_network = var.private_network
    }

    user_labels = {
      environment = "prod"
    }
  }
}

