# Terraform configuration for a highly available (regional) MySQL 8.0 Cloud SQL instance
# with automated backups enabled.

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    google = {
      source  = "hashicorp/google"
      version = "~> 8.0"
    }
  }
}

provider "google" {
  region = "us-central1"
}

resource "google_sql_database_instance" "mysql_ha_instance" {
  name             = "mysql-8-0-ha-instance"
  database_version = "MYSQL_8_0"
  region           = "us-central1"

  # Set to true in production to prevent accidental deletion
  deletion_protection = false

  settings {
    # HA configurations require a dedicated tier (shared-core like db-f1-micro is not supported for HA)
    tier              = "db-custom-2-7680"
    availability_type = "REGIONAL"

    disk_size       = 20
    disk_type       = "PD_SSD"
    disk_autoresize = true

    backup_configuration {
      enabled                        = true
      binary_log_enabled             = true # Required for point-in-time recovery and replication in MySQL
      start_time                     = "03:00"
      transaction_log_retention_days = 7

      backup_retention_settings {
        retained_backups = 7
        retention_unit   = "COUNT"
      }
    }

    ip_configuration {
      ipv4_enabled = true
    }
  }
}

