}

# The VPC network self-link is required to disable public IPv4 while allowing connectivity
# via Private Services Access.
variable "private_network" {
  type        = string
  description = "The self_link or ID of the VPC network configured with private services access for Cloud SQL."
}

resource "google_sql_database_instance" "mysql_ha" {
  name                = "mysql-ha-instance"
  database_version    = "MYSQL_8_0"
  region              = "asia-south1"
  deletion_protection = true

  settings {
    tier              = "db-custom-2-8192"
    availability_type = "REGIONAL"

    # For MySQL instances, binary_log_enabled is required for point-in-time recovery
    # and high availability failover; point_in_time_recovery_enabled is not supported.
    backup_configuration {
      enabled            = true
      binary_log_enabled = true
    }

    ip_configuration {
      ipv4_enabled    = false
      private_network = var.private_network
    }

    # Per organizational policy, resources must specify at least an environment label.
    # In Cloud SQL, labels are specified within settings.user_labels.
    user_labels = {
      environment = "prod"
    }
  }
}

