# Terraform configuration for Google Cloud KMS KeyRing and CryptoKey with automated rotation

terraform {
  required_version = ">= 1.5.0"
  required_providers {
    google = {
      source  = "hashicorp/google"
      version = "~> 8.0"
    }
  }
}

variable "project_id" {
  type        = string
  description = "The GCP project ID to host the KMS resources."
}

variable "location" {
  type        = string
  description = "The KMS location/region."
  default     = "us-central1"
}

variable "key_ring_name" {
  type        = string
  description = "The name of the KMS Key Ring."
  default     = "sample-key-ring"
}

variable "crypto_key_name" {
  type        = string
  description = "The name of the KMS Crypto Key."
  default     = "sample-symmetric-key"
}

# KMS Key Ring
resource "google_kms_key_ring" "key_ring" {
  project  = var.project_id
  name     = var.key_ring_name
  location = var.location
}

# Symmetric CryptoKey with 90-day automatic rotation
# 90 days * 24 hours * 60 minutes * 60 seconds = 7,776,000s
resource "google_kms_crypto_key" "crypto_key" {
  name            = var.crypto_key_name
  key_ring        = google_kms_key_ring.key_ring.id
  purpose         = "ENCRYPT_DECRYPT"
  rotation_period = "7776000s"

  version_template {
    algorithm        = "GOOGLE_SYMMETRIC_ENCRYPTION"
    protection_level = "SOFTWARE"
  }

  lifecycle {
    prevent_destroy = true
  }
}

output "key_ring_id" {
  description = "The ID of the created KMS Key Ring."
  value       = google_kms_key_ring.key_ring.id
}

output "crypto_key_id" {
  description = "The ID of the created KMS Crypto Key."
  value       = google_kms_crypto_key.crypto_key.id
}

