# Terraform configuration for hosting a public static website on Google Cloud Storage

terraform {
  required_version = ">= 1.5.0"
  required_providers {
    google = {
      source  = "hashicorp/google"
      version = "~> 8.0"
    }
  }
}

variable "project_id" {
  description = "The GCP project ID to deploy resources into"
  type        = string
}

variable "bucket_name" {
  description = "Globally unique name for the Cloud Storage bucket (e.g., example.com or my-site-bucket-12345)"
  type        = string
}

variable "location" {
  description = "The location for the bucket"
  type        = string
  default     = "US"
}

provider "google" {
  project = var.project_id
}

# Cloud Storage bucket configured for static website hosting
resource "google_storage_bucket" "website" {
  name          = var.bucket_name
  location      = var.location
  force_destroy = true

  # Ensure public access prevention is not actively blocking public access
  public_access_prevention = "inherited"

  # Uniform bucket-level access recommended by Google
  uniform_bucket_level_access = true

  # Website configuration for index and error pages
  website {
    main_page_suffix = "index.html"
    not_found_page   = "404.html"
  }

  # Optional CORS configuration allowing web clients to access resources
  cors {
    origin          = ["*"]
    method          = ["GET", "HEAD", "OPTIONS"]
    response_header = ["*"]
    max_age_seconds = 3600
  }
}

# Grant public read access to all objects in the bucket
resource "google_storage_bucket_iam_member" "public_read" {
  bucket = google_storage_bucket.website.name
  role   = "roles/storage.objectViewer"
  member = "allUsers"
}

# Output the website endpoints
output "bucket_name" {
  description = "The name of the static website bucket"
  value       = google_storage_bucket.website.name
}

output "website_url" {
  description = "The direct GCS public website endpoint"
  value       = "https://storage.googleapis.com/${google_storage_bucket.website.name}/index.html"
}

output "cname_url" {
  description = "The standard GCS website endpoint (if using a custom domain mapped via CNAME)"
  value       = "http://${google_storage_bucket.website.name}"
}

