# Terraform configuration for a MySQL Cloud SQL instance with public IP access
# configured specifically for direct access from an authorized office VPN network.

terraform {
  required_version = ">= 1.5.0"
  required_providers {
    google = {
      source  = "hashicorp/google"
      version = "~> 8.0"
    }
  }
}

variable "project_id" {
  description = "The GCP project ID to deploy the Cloud SQL instance in"
  type        = string
}

variable "region" {
  description = "The GCP region for the Cloud SQL instance"
  type        = string
  default     = "us-central1"
}

variable "instance_name" {
  description = "The name of the Cloud SQL instance"
  type        = string
  default     = "mysql-public-instance"
}

variable "database_version" {
  description = "The MySQL database engine version"
  type        = string
  default     = "MYSQL_8_0"
}

variable "tier" {
  description = "The machine tier for the database instance"
  type        = string
  default     = "db-custom-2-7680"
}

variable "office_vpn_cidr" {
  description = "The public CIDR block of the office VPN to allow direct connectivity"
  type        = string
  default     = "203.0.113.0/24" # Replace with your actual office VPN egress CIDR
}

variable "db_username" {
  description = "The default database username"
  type        = string
  default     = "appuser"
}

variable "db_password" {
  description = "The password for the default database user"
  type        = string
  sensitive   = true
}

provider "google" {
  project = var.project_id
  region  = var.region
}

resource "google_sql_database_instance" "mysql_instance" {
  name             = var.instance_name
  database_version = var.database_version
  region           = var.region

  deletion_protection = false

  settings {
    tier              = var.tier
    availability_type = "ZONAL"
    disk_size         = 20
    disk_type         = "PD_SSD"
    disk_autoresize   = true

    # Enable public IP connectivity and restrict access to the office VPN
    ip_configuration {
      ipv4_enabled = true
      ssl_mode     = "ENCRYPTED_ONLY"

      authorized_networks {
        name  = "office-vpn"
        value = var.office_vpn_cidr
      }
    }

    backup_configuration {
      enabled    = true
      start_time = "03:00"
    }
  }
}

resource "google_sql_database" "default_db" {
  name     = "appdb"
  instance = google_sql_database_instance.mysql_instance.name
  charset  = "utf8mb4"
  collation = "utf8mb4_unicode_ci"
}

resource "google_sql_user" "db_user" {
  name     = var.db_username
  instance = google_sql_database_instance.mysql_instance.name
  host     = "%"
  password = var.db_password
}

output "public_ip_address" {
  description = "The public IPv4 address assigned to the Cloud SQL MySQL instance"
  value       = google_sql_database_instance.mysql_instance.public_ip_address
}

output "connection_name" {
  description = "The connection name of the Cloud SQL MySQL instance"
  value       = google_sql_database_instance.mysql_instance.connection_name
}

terraform {
  required_providers {
    google = {
      source  = "hashicorp/google"
      version = "~> 8.0"
    }
  }
}

provider "google" {
  region = "asia-south1"
}

# Variable to restrict public access to the specific office VPN CIDR,
# complying with the organizational policy against 0.0.0.0/0 ingress.
variable "office_vpn_cidr" {
  type        = string
  description = "The CIDR range of the office VPN allowed to access the Cloud SQL instance"
  default     = "203.0.113.0/24"
}

resource "google_sql_database_instance" "mysql_instance" {
  name                = "corp-mysql-instance"
  database_version    = "MYSQL_8_0"
  region              = "asia-south1"
  deletion_protection = true

  settings {
    tier              = "db-custom-2-8192"
    availability_type = "REGIONAL"

    # Automated backups with binary logging enabled for MySQL point-in-time recovery and HA
    backup_configuration {
      enabled            = true
      binary_log_enabled = true
    }

    # Public IP enabled per requirement, restricted to the office VPN network
    ip_configuration {
      ipv4_enabled = true

      authorized_networks {
        name  = "office-vpn"
        value = var.office_vpn_cidr
      }
    }

    user_labels = {
      environment = "prod"
    }
  }
}

