# Cloud SQL MySQL instance configured per internal platform standards and checklist.
# Note: Public IP (ipv4_enabled = true) is explicitly enabled here per the ticket requirement
# because the office VPN cannot use the Cloud SQL Auth Proxy. Internal policy (data/policies/*.rego)
# typically rejects public IPs; an exception or specific authorized_networks CIDR block for the office
# gateway should be attached to restrict access rather than allowing 0.0.0.0/0.
resource "google_sql_database_instance" "mysql_instance" {
  name                = "app-mysql-instance"
  database_version    = "MYSQL_8_0"
  region              = "asia-south1"
  deletion_protection = true

  settings {
    tier              = "db-custom-2-8192"
    availability_type = "REGIONAL"

    # Per cloudsql-checklist.md: user_labels is used for google_sql_database_instance (not labels),
    # and environment is required by platform standards.
    user_labels = {
      environment = "prod"
    }

    # For MySQL engines, point_in_time_recovery_enabled is invalid and binary_log_enabled
    # must be used instead for PITR and regional HA.
    backup_configuration {
      enabled            = true
      binary_log_enabled = true
    }

    ip_configuration {
      ipv4_enabled = true

      # Specific authorized networks should be configured here for the office IP range.
      # The exact office IP range was not provided in the prompt context.
    }
  }
}

