# Terraform configuration for a MySQL Cloud SQL instance with Public IP access

terraform {
  required_version = ">= 1.5.0"
  required_providers {
    google = {
      source  = "hashicorp/google"
      version = "~> 8.0"
    }
    random = {
      source  = "hashicorp/random"
      version = ">= 3.5.0"
    }
  }
}

provider "google" {
  project = var.project_id
  region  = var.region
}

# --- Variables ---

variable "project_id" {
  type        = string
  description = "The Google Cloud Project ID."
}

variable "region" {
  type        = string
  description = "The region to host the database."
  default     = "us-central1"
}

variable "database_version" {
  type        = string
  description = "The MySQL version to use."
  default     = "MYSQL_8_0"
}

variable "tier" {
  type        = string
  description = "The machine type for the Cloud SQL instance."
  default     = "db-custom-2-7680"
}

variable "office_vpn_cidr" {
  type        = string
  description = "The public CIDR block of the office VPN to authorize access."
  default     = "203.0.113.0/24"
}

# --- Random Suffix & Password ---

# Cloud SQL instance names cannot be reused immediately after deletion.
# A random suffix avoids naming collisions during re-creation.
resource "random_id" "db_name_suffix" {
  byte_length = 4
}

resource "random_password" "db_password" {
  length  = 20
  special = true
}

# --- Cloud SQL Instance ---

resource "google_sql_database_instance" "mysql_instance" {
  name             = "mysql-public-${random_id.db_name_suffix.hex}"
  database_version = var.database_version
  region           = var.region

  deletion_protection = false

  settings {
    tier = var.tier

    # Public IP configuration
    ip_configuration {
      ipv4_enabled = true

      authorized_networks {
        name  = "office-vpn"
        value = var.office_vpn_cidr
      }
    }

    backup_configuration {
      enabled            = true
      binary_log_enabled = true
    }
  }
}

# --- Database & User ---

resource "google_sql_database" "default" {
  name     = "app_database"
  instance = google_sql_database_instance.mysql_instance.name
  charset  = "utf8mb4"
  collation = "utf8mb4_unicode_ci"
}

resource "google_sql_user" "default" {
  name     = "app_user"
  instance = google_sql_database_instance.mysql_instance.name
  host     = "%" # Allows connection from authorized public IP ranges
  password = random_password.db_password.result
}

# --- Outputs ---

output "instance_public_ip" {
  description = "The public IPv4 address assigned to the Cloud SQL instance."
  value       = google_sql_database_instance.mysql_instance.public_ip_address
}

output "instance_connection_name" {
  description = "The connection name of the Cloud SQL instance."
  value       = google_sql_database_instance.mysql_instance.connection_name
}

output "database_name" {
  description = "Name of the created database."
  value       = google_sql_database"default".name
}

output "database_user" {
  description = "Application database username."
  value       = google_sql_user.default.name
}

output "database_password" {
  description = "Application database password."
  value       = random_password.db_password.result
  sensitive   = true
}

