  type        = string
}

variable "location" {
  description = "The GCS location/region for the bucket."
  type        = string
  default     = "US"
}

resource "google_storage_bucket" "secure_bucket" {
  name     = var.bucket_name
  project  = var.project_id
  location = var.location

  # Enforce uniform bucket-level access (disables ACLs)
  uniform_bucket_level_access = true

  # Enforce public access prevention to disallow all public access
  public_access_prevention = "enforced"

  # Prevent accidental deletion of the bucket
  force_destroy = false
}

output "bucket_name" {
  description = "The name of the created storage bucket."
  value       = google_storage_bucket.secure_bucket.name
}

output "bucket_url" {
  description = "The base URL of the bucket, in the format gs://<bucket-name>."
  value       = google_storage_bucket.secure_bucket.url
}

