# Terraform configuration for hosting a public static website using Google Cloud Storage

terraform {
  required_version = ">= 1.0"
  required_providers {
    google = {
      source  = "hashicorp/google"
      version = "~> 8.0"
    }
  }
}

variable "project_id" {
  description = "The ID of the Google Cloud project."
  type        = string
}

variable "bucket_name" {
  description = "The name of the GCS bucket. Must be globally unique (or a verified domain name if using CNAME)."
  type        = string
}

variable "location" {
  description = "The GCS location for the bucket."
  type        = string
  default     = "US"
}

provider "google" {
  project = var.project_id
}

# Cloud Storage bucket configured for static website hosting
resource "google_storage_bucket" "static_website" {
  name          = var.bucket_name
  location      = var.location
  force_destroy = true

  # Uniform bucket-level access simplifies IAM permissions across all objects
  uniform_bucket_level_access = true

  # Website configuration for serving index and error pages
  website {
    main_page_suffix = "index.html"
    not_found_page   = "404.html"
  }

  # Ensure public access is not prevented at the bucket level
  public_access_prevention = "inherited"
}

# Grant public read access to all objects in the bucket to the internet
resource "google_storage_bucket_iam_member" "public_access" {
  bucket = google_storage_bucket.static_website.name
  role   = "roles/storage.objectViewer"
  member = "allUsers"
}

output "website_url" {
  description = "The direct storage URL for the static website."
  value       = "https://storage.googleapis.com/${google_storage_bucket.static_website.name}/index.html"
}

output "bucket_name" {
  description = "The name of the created Cloud Storage bucket."
  value       = google_storage_bucket.static_website.name
}

