variable "bucket_name" {
  type        = string
  description = "Globally unique name for the static website Cloud Storage bucket"
  default     = "static-website-bucket-asia-south1"
}

# Cloud Storage bucket configured for static website hosting
resource "google_storage_bucket" "static_website" {
  name     = var.bucket_name
  location = "asia-south1" # Defaulted to org standard region (Mumbai)

  uniform_bucket_level_access = true

  website {
    main_page_suffix = "index.html"
    not_found_page   = "404.html"
  }

  # Retention requirement: versioning enabled to protect against unintended overwrites/deletions
  versioning {
    enabled = true
  }

  # Mandatory organizational labels
  labels = {
    environment = "prod"
    purpose     = "static-website"
    managed_by  = "terraform"
  }
}

# Public read access granted to allUsers as explicitly required for public website hosting
resource "google_storage_bucket_iam_member" "public_read" {
  bucket = google_storage_bucket.static_website.name
  role   = "roles/storage.objectViewer"
  member = "allUsers"
}

# Terraform configuration for a MySQL Cloud SQL instance with public IP access
# configured for an authorized office VPN network.

terraform {
  required_version = ">= 1.5.0"
  required_providers {
    google = {
      source  = "hashicorp/google"
      version = "~> 8.0"
    }
  }
}

variable "project_id" {
  type        = string
  description = "The GCP project ID to deploy the Cloud SQL instance in."
}

variable "region" {
  type        = string
  description = "The GCP region for the Cloud SQL instance."
  default     = "us-central1"
}

variable "instance_name" {
  type        = string
  description = "Name of the Cloud SQL database instance."
  default     = "mysql-public-instance"
}

variable "database_version" {
  type        = string
  description = "MySQL engine version."
  default     = "MYSQL_8_0"
}

variable "tier" {
  type        = string
  description = "Machine tier for the database instance."
  default     = "db-custom-2-7680"
}

variable "office_vpn_cidr" {
  type        = string
  description = "The public CIDR block of the office VPN to allow inbound MySQL traffic."
  default     = "203.0.113.0/24" # Example RFC 5737 documentation CIDR; replace with actual office IP/CIDR
}

variable "db_user" {
  type        = string
  description = "Username for the initial database user."
  default     = "app_user"
}

variable "db_password" {
  type        = string
  description = "Password for the initial database user."
  sensitive   = true
}

provider "google" {
  project = var.project_id
  region  = var.region
}

# Cloud SQL MySQL Instance with Public IPv4 and Authorized Networks
resource "google_sql_database_instance" "mysql_instance" {
  name                = var.instance_name
  database_version    = var.database_version
  region              = var.region
  deletion_protection = true

  settings {
    tier              = var.tier
    availability_type = "REGIONAL"
    disk_size         = 20
    disk_type         = "PD_SSD"
    disk_autoresize   = true

    ip_configuration {
      # Enable external/public IPv4 allocation
      ipv4_enabled = true

      # Restrict access to the Office VPN CIDR block
      authorized_networks {
        name  = "office-vpn"
        value = var.office_vpn_cidr
      }

      # Enforce SSL/TLS encryption for all in-transit connections
      ssl_mode = "ENCRYPTED_ONLY"
    }

    backup_configuration {
      enabled                        = true
      binary_log_enabled             = true
      start_time                     = "03:00"
      point_in_time_recovery_enabled = true
    }
  }
}

# Initial MySQL Database
resource "google_sql_database" "default_db" {
  name     = "app_db"
  instance = google_sql_database_instance.mysql_instance.name
  charset  = "utf8mb4"
  collation = "utf8mb4_unicode_ci"
}

# Initial MySQL User allowed to connect from the authorized public IP
resource "google_sql_user" "default_user" {
  name     = var.db_user
  instance = google_sql_database_instance.mysql_instance.name
  host     = "%" # Wildcard host or restrict to the specific office public IP
  password = var.db_password
}

# Outputs for connecting to the instance
output "public_ip_address" {
  description = "The assigned public IPv4 address of the Cloud SQL instance."
  value       = google_sql_database_instance.mysql_instance.public_ip_address
}

output "connection_name" {
  description = "The connection name of the Cloud SQL instance."
  value       = google_sql_database_instance.mysql_instance.connection_name
}

