# Cloud SQL MySQL Instance with public IPv4 enabled per requirement.
# Public ingress is restricted to the office VPN CIDR block to satisfy org security policy
# prohibiting unrestricted 0.0.0.0/0 access.
resource "google_sql_database_instance" "mysql" {
  name                = "app-mysql-instance"
  database_version    = "MYSQL_8_0"
  region              = "asia-south1"
  deletion_protection = true

  settings {
    tier              = "db-custom-2-8192"
    availability_type = "REGIONAL"

    backup_configuration {
      enabled            = true
      binary_log_enabled = true # Binary logging is required for MySQL point-in-time recovery and HA
    }

    ip_configuration {
      ipv4_enabled = true

      authorized_networks {
        name  = "office-vpn"
        value = var.office_vpn_cidr
      }
    }

    user_labels = {
      environment = "prod"
    }
  }
}

