}

resource "random_id" "db_name_suffix" {
  byte_length = 4
}

# Cloud SQL MySQL instance configured with a public IP per explicit requirement
resource "google_sql_database_instance" "default" {
  name                = "mysql-public-instance-${random_id.db_name_suffix.hex}"
  region              = var.region
  database_version    = "MYSQL_8_0"
  deletion_protection = true

  settings {
    tier              = "db-custom-2-8192"
    availability_type = "ZONAL"

    backup_configuration {
      enabled            = true
      binary_log_enabled = true # Required for point-in-time recovery on MySQL instances
    }

    ip_configuration {
      # Public IP explicitly enabled per user requirement for office VPN direct access
      ipv4_enabled = true

      authorized_networks {
        name  = "office-vpn"
        value = var.office_ip_cidr
      }
    }
  }
}

# Terraform configuration for Google Cloud Platform
# Target provider: hashicorp/google ~> 8.0

terraform {
