      version = "~> 8.0"
    }
  }
}

provider "google" {
  region = "asia-south1"
}

# Cloud SQL MySQL Instance configured with public IP as explicitly requested.
# Note on public IP and security:
# - ipv4_enabled = true assigns a public IPv4 address.
# - The retrieved context notes that private IP via Shared VPC is normally mandatory,
#   and 0.0.0.0/0 public access is prohibited by platform standards.
# - Specific office IP CIDR blocks should be added to authorized_networks inside
#   ip_configuration to restrict access to trusted office ranges only.
resource "google_sql_database_instance" "mysql_instance" {
  name                = "app-mysql-asia-south1"
  database_version    = "MYSQL_8_0"
  region              = "asia-south1"
  deletion_protection = true

  settings {
    tier              = "db-custom-2-8192"
    availability_type = "REGIONAL"

    user_labels = {
      environment = "prod"
    }

    # For MySQL engines, PITR and regional HA require binary logging instead of point_in_time_recovery_enabled
    backup_configuration {
      enabled            = true
      binary_log_enabled = true
    }

    ip_configuration {
      # Public IP requested due to VPN limitations with Cloud SQL Auth Proxy
      ipv4_enabled = true

      # The specific office IP range was not provided in the prompt context.
      # Define authorized networks here with specific office CIDRs rather than 0.0.0.0/0.
      # authorized_networks {
      #   name  = "office-vpn"
      #   value = "203.0.113.0/24"
      # }
    }
  }
}

